import math

def task_func(f):
    argspec = inspect.getfullargspec(f)
    num_args = len(argspec.args) if argspec.args else 0
    sqrt_args = math.sqrt(num_args) if num_args > 0 else 0
    lambda_count = 0
    if argspec.defaults:
        for default in argspec.defaults:
            if isinstance(default, types.LambdaType):
                lambda_count += 1
    return {
        'name': f.__name__,
        'sqrt_args': sqrt_args,
        'lambda_count': lambda_count
    }

